def _norm(value) -> str:
    text = " ".join(str(value or "").replace("amp;", "&").strip().split()).upper()
    text = text.replace("Đ", "D")
    text = unicodedata.normalize("NFD", text)
    text = "".join(ch for ch in text if unicodedata.category(ch) != "Mn")
    text = re.sub(r"[^A-Z0-9]+", " ", text).strip()
    return " ".join(text.split())


def _commune_base(value) -> str:
    text = _norm(value)
    for prefix in ("PHUONG ", "XA ", "THI TRAN "):
        if text.startswith(prefix):
            return text[len(prefix):].strip()
    return text


def _clean(value) -> str:
    return " ".join(str(value or "").replace("amp;", "&").strip().split())


def _parse_date(value):
    text = _clean(value)
    for fmt in ("%d/%m/%Y", "%Y-%m-%d"):
        try:
            return datetime.strptime(text, fmt).date()
        except Exception:
            pass
    return None


def _status_priority(label) -> int:
    return {
        "CHUYEN DEN": 100,
        "DANG LAM VIEC": 90,
        "DA BIET PHAI": 60,
        "DA DIEU DONG": 50,
        "CHO NGHI HUU": 40,
        "DA CHUYEN DI": 20,
        "DA NGHI HUU": 10,
        "THOI VIEC": 5,
    }.get(_norm(label), 1)


def _is_current(label) -> bool:
    return _norm(label) in {"DANG LAM VIEC", "CHUYEN DEN"}


def _map_status(label) -> str:
    n = _norm(label)
    if n in {"CHUYEN DEN", "DANG LAM VIEC"}:
        return "DANG_LAM_VIEC"
    if "NGHI HUU" in n:
        return "NGHI_HUU"
    if "THOI VIEC" in n or "NGHI VIEC" in n:
        return "NGHI_VIEC"
    if "CHUYEN DI" in n or "DIEU DONG" in n:
        return "CHUYEN_DI"
    if "BIET PHAI" in n or "CHO NGHI HUU" in n:
        return "TAM_NGHI"
    return "TAM_NGHI"


def _map_position(value) -> str:
    n = _norm(value)
    if "CAN BO QUAN LY" in n:
        return "CBQL"
    if "NHAN VIEN" in n:
        return "NHAN_VIEN"
    return "GIAO_VIEN"


def _map_employment(value) -> str:
    n = _norm(value)
    if "KHONG XAC DINH THOI HAN" in n:
        return "BIEN_CHE"
    if "VIEN CHUC" in n or "CONG CHUC" in n:
        return "HOP_DONG_LAM_VIEC"
    if "HOP DONG" in n or "THINH GIANG" in n:
        return "HOP_DONG_LAO_DONG"
    return "CHUA_XAC_DINH"


def _map_qualification(value) -> str:
    n = _norm(value)
    if "TIEN SI" in n:
        return "TIEN_SI"
    if "THAC SI" in n:
        return "THAC_SI"
    if "DAI HOC" in n:
        return "DAI_HOC"
    if "CAO DANG" in n:
        return "CAO_DANG"
    if "TRUNG CAP" in n:
        return "TRUNG_CAP"
    if n:
        return "KHAC"
    return "CHUA_XAC_DINH"


def _source_level_code(levels) -> str:
    levels = set(levels)
    if levels == {"TH", "THCS"}:
        return "LIEN_CAP_TH_THCS"
    if "TH" in levels:
        return "TIEU_HOC"
    if "THCS" in levels:
        return "THCS"
    return "KHONG_DAY"


def _qual_cat(value) -> str:
    n = _norm(value)
    if "TIEN SI" in n or "THAC SI" in n:
        return "postgrad"
    if "DAI HOC" in n:
        return "university"
    if "CAO DANG" in n:
        return "college"
    if "TRUNG CAP" in n:
        return "secondary"
    if "DUOI THSP" in n:
        return "below"
    return "other"


def _th_training(row) -> str:
    text = _norm((row.get("main_specialty") or "") + " " + (row.get("subject") or ""))
    if "GIAO DUC TIEU HOC" in text or _norm(row.get("subject")) == "TIEU HOC":
        return "primary"
    if "AM NHAC" in text:
        return "music"
    if "MY THUAT" in text:
        return "art"
    if "THE DUC" in text or "GIAO DUC THE CHAT" in text:
        return "pe"
    if "TIN HOC" in text:
        return "it"
    if any(x in text for x in ("TIENG ANH", "NGOAI NGU", "TIENG PHAP", "TIENG NGA")):
        return "foreign"
    return "other"


def _thcs_subject(row) -> str:
    n = _norm(row.get("subject"))
    exact = {
        "TOAN": "math",
        "NGU VAN": "literature",
        "VAT LY": "physics",
        "HOA HOC": "chemistry",
        "SINH HOC": "biology",
        "LICH SU": "history",
        "DIA LY": "geography",
        "AM NHAC": "music",
        "MY THUAT": "art",
        "THE DUC": "pe",
        "GIAO DUC THE CHAT": "pe",
        "GIAO DUC CONG DAN": "civic",
        "CONG NGHE": "technology",
        "TIN HOC": "it",
        "TIENG ANH": "english",
        "TIENG NGA": "russian",
        "TIENG PHAP": "french",
    }
    # Các môn tích hợp/khác không tự chia sang môn thành phần.
    return exact.get(n, "other")


def _aggregate_staff(level: str, rows: list[dict]) -> dict:
    managers = [r for r in rows if _map_position(r.get("position")) == "CBQL"]
    teachers = [r for r in rows if _map_position(r.get("position")) == "GIAO_VIEN"]
    employees = [r for r in rows if _map_position(r.get("position")) == "NHAN_VIEN"]

    data = {
        "principal": sum(
            1 for r in managers
            if "HIEU TRUONG" in _norm(r.get("position_title"))
            and "PHO" not in _norm(r.get("position_title"))
        ),
        "vice_principal": sum(
            1 for r in managers
            if "PHO HIEU TRUONG" in _norm(r.get("position_title"))
        ),
        "teacher_total": len(teachers),
        "teacher_permanent": sum(
            1 for r in teachers if _map_employment(r.get("employment")) == "BIEN_CHE"
        ),
        "teacher_female": sum(1 for r in teachers if _norm(r.get("gender")) == "NU"),
        "teacher_ethnic": sum(
            1 for r in teachers
            if _clean(r.get("ethnic_group")) and _norm(r.get("ethnic_group")) != "KINH"
        ),
    }
    data["teacher_contract"] = data["teacher_total"] - data["teacher_permanent"]

    qual = defaultdict(int)
    for row in teachers:
        qual[_qual_cat(row.get("qualification"))] += 1
    data.update({
        "qual_postgrad": qual["postgrad"],
        "qual_university": qual["university"],
        "qual_college": qual["college"],
        "qual_secondary": qual["secondary"],
    })

    team_leader = sum(
        1 for r in rows if "TONG PHU TRACH" in _norm(r.get("position_title"))
    )
    if team_leader:
        data["team_leader"] = team_leader

    if level == "TH":
        data["qual_below_secondary"] = qual["below"]
        training = defaultdict(int)
        for row in teachers:
            training[_th_training(row)] += 1
        data.update({
            "training_primary": training["primary"],
            "training_music": training["music"],
            "training_art": training["art"],
            "training_pe": training["pe"],
            "training_it": training["it"],
            "training_foreign": training["foreign"],
            "training_other": training["other"],
        })
        office = 0
        library_equipment = 0
        for row in employees:
            title = _norm(row.get("position_title"))
            if any(x in title for x in ("THU VIEN", "THIET BI", "THI NGHIEM")):
                library_equipment += 1
            elif any(x in title for x in ("VAN THU", "KE TOAN", "THU QUY", "GIAO VU", "VAN PHONG")):
                office += 1
        data["employee_office"] = office
        data["employee_library_equipment"] = library_equipment
    else:
        subjects = defaultdict(int)
        for row in teachers:
            subjects[_thcs_subject(row)] += 1
        for key in (
            "math", "literature", "physics", "chemistry", "biology", "history",
            "geography", "music", "art", "pe", "civic", "technology", "it",
            "english", "russian", "french", "other",
        ):
            data["subject_" + key] = subjects[key]

        emp = defaultdict(int)
        for row in employees:
            title = _norm(row.get("position_title"))
            if "THU VIEN" in title:
                emp["library"] += 1
            elif "THIET BI" in title or "THI NGHIEM" in title:
                emp["equipment_lab"] += 1
            elif "Y TE" in title:
                emp["health"] += 1
            elif any(x in title for x in ("VAN THU", "KE TOAN", "THU QUY", "GIAO VU", "VAN PHONG")):
                emp["office"] += 1
        data.update({
            "employee_library": emp["library"],
            "employee_equipment_lab": emp["equipment_lab"],
            "employee_health": emp["health"],
            "employee_office": emp["office"],
        })

    return data


def _read_text(rel: str) -> str:
    path = PROJECT / rel
    if not path.exists():
        raise RuntimeError(f"Không tìm thấy tệp bắt buộc: {path}")
    return path.read_text(encoding="utf-8-sig")


def _verify_base() -> None:
    checks = {
        "app/routers/report_inputs.py": ["BAI_13B_6_V1_STRUCTURED_INPUT_START"],
        "app/templates/report_inputs/structured_school_form.html": [
            "BAI_13B_6_V1_1_SAFE_SCOPE_SUBMIT",
            "structured-data-form",
        ],
        "app/templates/report_inputs/gv_mn01.html": ["BAI_13B_6_V1_1_SAFE_SCOPE_SUBMIT"],
        "app/templates/report_inputs/csvc_mn01.html": ["BAI_13B_6_V1_1_SAFE_SCOPE_SUBMIT"],
        "app/templates/partials/dropdown_menu_v1.html": [
            "BAI_13B_5_V1_TEAM_MENU_START",
            "BAI_13B_5_V1_CSVC_MENU_START",
            "/bieu-nhap/th-01-gv",
            "/bieu-nhap/thcs-01-csvc",
        ],
    }
    for rel, markers in checks.items():
        text = _read_text(rel)
        for marker in markers:
            if marker not in text:
                raise RuntimeError(
                    f"Chưa đúng nền Bài 13B-6 V1.1: {rel} / {marker}. "
                    "Không cài để tránh ảnh hưởng phần đang chạy tốt."
                )


def _backup_files() -> list[dict]:
    BACKUP.mkdir(parents=True, exist_ok=False)
    manifest = []
    for rel in FILES_TO_BACKUP:
        src = PROJECT / rel
        existed = src.exists()
        manifest.append({"path": rel, "existed": existed})
        if existed:
            dst = BACKUP / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)
    MANIFEST.write_text(
        json.dumps(manifest, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return manifest


def _restore(manifest: list[dict]) -> None:
    for item in reversed(manifest):
        target = PROJECT / item["path"]
        if item["existed"]:
            src = BACKUP / item["path"]
            if src.exists():
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src, target)
        elif target.exists() and target.is_file():
            target.unlink()


def _write_payload() -> None:
    for rel, encoded in PAYLOAD.items():
        target = PROJECT / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(gzip.decompress(base64.b64decode(encoded.encode("ascii"))))


def _migrate_sqlite_columns() -> list[str]:
    if not DB.exists():
        raise RuntimeError(f"Không tìm thấy database: {DB}")

    con = sqlite3.connect(DB)
    added = []
    try:
        def table_exists(name: str) -> bool:
            return con.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",
                (name,),
            ).fetchone() is not None

        def columns(name: str) -> set[str]:
            return {str(row[1]) for row in con.execute(f"PRAGMA table_info({name})").fetchall()}

        migrations = {
            "staff_members": [
                ("ethnic_group", "VARCHAR(100)"),
            ],
            "staff_year_records": [
                ("teaching_subject", "VARCHAR(200)"),
                ("main_specialty", "VARCHAR(250)"),
                ("staff_evaluation", "VARCHAR(120)"),
                ("source_level", "VARCHAR(20)"),
                ("source_status_label", "VARCHAR(100)"),
            ],
        }

        for table, items in migrations.items():
            if not table_exists(table):
                continue
            existing = columns(table)
            for col, decl in items:
                if col not in existing:
                    con.execute(f"ALTER TABLE {table} ADD COLUMN {col} {decl}")
                    added.append(f"{table}.{col}")
        con.commit()
    finally:
        con.close()
    return added


def _compile_and_check_templates() -> None:
    for rel in (
        "app/report_input_models.py",
        "app/routers/report_inputs.py",
        "app/pcgd_xmc_report_builders_v1.py",
        "app/staff_models.py",
        "app/routers/staff_management.py",
    ):
        subprocess.run(
            [sys.executable, "-m", "py_compile", str(PROJECT / rel)],
            cwd=PROJECT,
            check=True,
        )

    from jinja2 import Environment, FileSystemLoader
    env = Environment(loader=FileSystemLoader(str(APP / "templates")))
    for name in (
        "report_inputs/structured_school_form.html",
        "staff/list.html",
        "staff/form.html",
        "partials/dropdown_menu_v1.html",
        "report_inputs/gv_mn01.html",
        "report_inputs/csvc_mn01.html",
    ):
        env.get_template(name)


def _decode_dataset(encoded: str) -> dict:
    raw = gzip.decompress(base64.b64decode(encoded.encode("ascii")))
    return json.loads(raw.decode("utf-8"))


def _import_all() -> dict:
    from sqlalchemy import select, func
    from app.database import Base, SessionLocal, engine
    from app.models import Commune, School, SchoolYear
    from app.report_input_models import SchoolNetworkYearData, SchoolStructuredReportInput
    from app.staff_models import StaffMember, StaffYearRecord

    Base.metadata.create_all(bind=engine)

    network = _decode_dataset(NETWORK_DATA_B64)
    staff = _decode_dataset(STAFF_DATA_B64)
    source_year_code = str(network.get("source_year") or staff.get("source_year") or "2025-2026")
    network_rows = list(network.get("records") or [])
    staff_rows = list(staff.get("records") or [])

    stats = {
        "network_source_rows": len(network_rows),
        "staff_source_rows": len(staff_rows),
        "schools_created": 0,
        "schools_existing": 0,
        "schools_moved_commune": 0,
        "network_created": 0,
        "network_updated": 0,
        "network_skipped": 0,
        "staff_level_groups": 0,
        "staff_global_unique": 0,
        "staff_school_unmatched": 0,
        "staff_members_created": 0,
        "staff_members_reused": 0,
        "staff_records_created": 0,
        "staff_records_enriched": 0,
        "structured_created": 0,
        "structured_updated": 0,
        "active_th": 0,
        "active_thcs": 0,
        "active_teacher_th": 0,
        "active_teacher_thcs": 0,
        "unmatched_communes": set(),
    }

    db = SessionLocal()
    try:
        year = db.scalar(select(SchoolYear).where(SchoolYear.code == source_year_code))
        if year is None:
            year = SchoolYear(
                code=source_year_code,
                name=f"Năm học {source_year_code}",
                is_active=True,
            )
            db.add(year)
            db.flush()

        communes = list(db.scalars(select(Commune).where(Commune.is_active.is_(True))).all())
        full_map = defaultdict(list)
        base_map = defaultdict(list)
        for commune in communes:
            full_map[_norm(commune.name)].append(commune)
            base_map[_commune_base(commune.name)].append(commune)

        def find_commune(name):
            name = _clean(name)
            if not name:
                return None
            full = full_map.get(_norm(name), [])
            if len(full) == 1:
                return full[0]
            base = base_map.get(_commune_base(name), [])
            if len(base) == 1:
                return base[0]
            return None

        # Dùng danh sách đội ngũ để bổ sung xã cho các trường trực thuộc Sở
        # mà file mạng lưới không ghi xã/phường.
        teacher_communes = defaultdict(set)
        for row in staff_rows:
            level = _clean(row.get("level")).upper()
            school_name = _norm(row.get("school_name"))
            commune_name = _clean(row.get("commune_name"))
            if level in {"TH", "THCS"} and school_name and commune_name:
                teacher_communes[(level, school_name)].add(commune_name)

        schools_by_code = {str(s.code or "").strip(): s for s in db.scalars(select(School)).all()}

        # 1. Nhập mạng lưới trường/lớp.
        for row in network_rows:
            level = _clean(row.get("level")).upper()
            code = _clean(row.get("school_code"))
            school_name = _clean(row.get("school_name"))
            commune_name = _clean(row.get("commune_name"))
            if level not in {"TH", "THCS"} or not code:
                continue

            if not commune_name:
                candidates = {x for x in teacher_communes.get((level, _norm(school_name)), set()) if x}
                if len(candidates) == 1:
                    commune_name = next(iter(candidates))

            commune = find_commune(commune_name) if commune_name else None
            school = schools_by_code.get(code)

            if school is None:
                if commune is None:
                    stats["network_skipped"] += 1
                    if commune_name:
                        stats["unmatched_communes"].add(commune_name)
                    continue
                school = School(
                    commune_id=int(commune.id),
                    code=code,
                    name=school_name or code,
                    is_active=True,
                )
                db.add(school)
                db.flush()
                schools_by_code[code] = school
                stats["schools_created"] += 1
            else:
                stats["schools_existing"] += 1
                if commune is not None and int(school.commune_id) != int(commune.id):
                    school.commune_id = int(commune.id)
                    stats["schools_moved_commune"] += 1
                if not _clean(school.name) and school_name:
                    school.name = school_name
                school.is_active = True

            rec = db.scalar(
                select(SchoolNetworkYearData).where(
                    SchoolNetworkYearData.school_id == int(school.id),
                    SchoolNetworkYearData.school_year_id == int(year.id),
                    SchoolNetworkYearData.level_code == level,
                )
            )
            if rec is None:
                rec = SchoolNetworkYearData(
                    school_id=int(school.id),
                    school_year_id=int(year.id),
                    level_code=level,
                )
                db.add(rec)
                stats["network_created"] += 1
            else:
                stats["network_updated"] += 1

            rec.data_json = json.dumps(
                row.get("data") or {},
                ensure_ascii=False,
                separators=(",", ":"),
            )
            rec.source_name = (
                "Thong_ke_mang_luoi_lop_HS_GV_TH.xlsx"
                if level == "TH"
                else "Thong_ke_mang_luoi_lop_HS_GV_THCS.xlsx"
            )

        db.commit()

        # Map tên trường theo cấp từ dữ liệu mạng lưới đã tạo.
        school_by_level_name = {}
        for row in network_rows:
            level = _clean(row.get("level")).upper()
            code = _clean(row.get("school_code"))
            school = schools_by_code.get(code)
            if school is not None:
                school_by_level_name[(level, _norm(row.get("school_name")))] = school

        # 2. Chọn bản ghi nguồn tốt nhất của mỗi người trong từng cấp.
        grouped = defaultdict(list)
        for row in staff_rows:
            level = _clean(row.get("level")).upper()
            code = _clean(row.get("staff_code"))
            if level in {"TH", "THCS"} and code:
                grouped[(level, code)].append(row)

        level_best = {}
        for key, rows in grouped.items():
            best = max(rows, key=lambda r: (_status_priority(r.get("status")), int(r.get("source_row") or 0)))
            school = school_by_level_name.get((best.get("level"), _norm(best.get("school_name"))))
            if school is None:
                stats["staff_school_unmatched"] += 1
                continue
            level_best[key] = (best, school)
        stats["staff_level_groups"] = len(level_best)

        # 3. Tạo hồ sơ đội ngũ toàn tỉnh nhưng không ghi đè dữ liệu người dùng đã có.
        members_by_ministry = {
            _clean(m.ministry_staff_code): m
            for m in db.scalars(select(StaffMember)).all()
            if _clean(m.ministry_staff_code)
        }
        members_by_code = {
            _clean(m.code): m
            for m in db.scalars(select(StaffMember)).all()
            if _clean(m.code)
        }
        all_member_codes = set(members_by_code)
        year_records = {
            (int(r.staff_member_id), int(r.school_year_id)): r
            for r in db.scalars(select(StaffYearRecord)).all()
        }

        # Một mã nhân sự có thể xuất hiện ở cả TH và THCS; dùng một hồ sơ nhận diện chung.
        global_by_code = defaultdict(list)
        for (level, code), (row, school) in level_best.items():
            global_by_code[code].append((row, school))
        stats["staff_global_unique"] = len(global_by_code)

        max_member_id = db.scalar(select(func.max(StaffMember.id))) or 0

        def next_internal_code():
            nonlocal max_member_id
            while True:
                max_member_id += 1
                candidate = f"NS-{max_member_id:08d}"
                if candidate not in all_member_codes:
                    all_member_codes.add(candidate)
                    return candidate

        for index, (ministry_code, items) in enumerate(global_by_code.items(), start=1):
            best_row, best_school = max(
                items,
                key=lambda pair: (
                    _status_priority(pair[0].get("status")),
                    int(pair[0].get("source_row") or 0),
                ),
            )

            member = members_by_ministry.get(ministry_code) or members_by_code.get(ministry_code)
            if member is None:
                member = StaffMember(
                    code=next_internal_code(),
                    ministry_staff_code=ministry_code,
                    full_name=_clean(best_row.get("full_name")) or ministry_code,
                    date_of_birth=_parse_date(best_row.get("date_of_birth")),
                    gender=_clean(best_row.get("gender")) or None,
                    ethnic_group=_clean(best_row.get("ethnic_group")) or None,
                    is_active=True,
                )
                db.add(member)
                db.flush()
                members_by_ministry[ministry_code] = member
                stats["staff_members_created"] += 1
            else:
                stats["staff_members_reused"] += 1
                # Chỉ bổ sung phần còn trống, không ghi đè dữ liệu hiện có.
                if not _clean(getattr(member, "ministry_staff_code", None)):
                    try:
                        member.ministry_staff_code = ministry_code
                    except Exception:
                        pass
                if not _clean(getattr(member, "ethnic_group", None)) and _clean(best_row.get("ethnic_group")):
                    member.ethnic_group = _clean(best_row.get("ethnic_group"))
                if not _clean(getattr(member, "gender", None)) and _clean(best_row.get("gender")):
                    member.gender = _clean(best_row.get("gender"))
                if getattr(member, "date_of_birth", None) is None:
                    member.date_of_birth = _parse_date(best_row.get("date_of_birth"))

            key = (int(member.id), int(year.id))
            record = year_records.get(key)

            current_levels_same_school = {
                str(r.get("level"))
                for r, school in items
                if _is_current(r.get("status")) and int(school.id) == int(best_school.id)
            }
            teaching_level = _source_level_code(current_levels_same_school or {best_row.get("level")})

            notes_parts = [f"Nguồn {best_row.get('level')} {source_year_code}"]
            if _clean(best_row.get("subject")):
                notes_parts.append(f"Môn dạy: {_clean(best_row.get('subject'))}")
            if _clean(best_row.get("main_specialty")):
                notes_parts.append(f"Chuyên ngành: {_clean(best_row.get('main_specialty'))}")
            if _clean(best_row.get("status")):
                notes_parts.append(f"Trạng thái nguồn: {_clean(best_row.get('status'))}")
            notes = " | ".join(notes_parts)

            if record is None:
                record = StaffYearRecord(
                    staff_member_id=int(member.id),
                    school_year_id=int(year.id),
                    school_id=int(best_school.id),
                    status_code=_map_status(best_row.get("status")),
                    position_group=_map_position(best_row.get("position")),
                    position_title=_clean(best_row.get("position_title")) or _clean(best_row.get("position")) or None,
                    employment_type=_map_employment(best_row.get("employment")),
                    teaching_level=teaching_level,
                    teaching_age_group="KHONG_XAC_DINH",
                    teaching_subject=_clean(best_row.get("subject")) or None,
                    main_specialty=_clean(best_row.get("main_specialty")) or None,
                    staff_evaluation=_clean(best_row.get("evaluation")) or None,
                    source_level=_clean(best_row.get("level")) or None,
                    source_status_label=_clean(best_row.get("status")) or None,
                    qualification_level=_map_qualification(best_row.get("qualification")),
                    qualification_standard="CHUA_XAC_DINH",
                    professional_standard="CHUA_DANH_GIA",
                    notes=notes or None,
                    is_active=True,
                )
                db.add(record)
                db.flush()
                year_records[key] = record
                stats["staff_records_created"] += 1
            else:
                changed = False
                # Không đổi trường, chức vụ, trạng thái, trình độ... nếu người dùng đã có bản ghi.
                enrich = (
                    ("teaching_subject", _clean(best_row.get("subject")) or None),
                    ("main_specialty", _clean(best_row.get("main_specialty")) or None),
                    ("staff_evaluation", _clean(best_row.get("evaluation")) or None),
                    ("source_level", _clean(best_row.get("level")) or None),
                    ("source_status_label", _clean(best_row.get("status")) or None),
                )
                for attr, value in enrich:
                    if not _clean(getattr(record, attr, None)) and value:
                        setattr(record, attr, value)
                        changed = True
                if changed:
                    stats["staff_records_enriched"] += 1

            if index % 4000 == 0:
                db.flush()

        db.commit()

        # 4. Tự động tổng hợp dữ liệu nguồn vào TH-01-GV / THCS-01-GV.
        # Chỉ dùng người Đang làm việc hoặc Chuyển đến; dữ liệu người dùng nhập trước luôn được ưu tiên.
        per_school_level = defaultdict(list)
        for (level, _code), (row, school) in level_best.items():
            if _is_current(row.get("status")):
                per_school_level[(level, int(school.id))].append(row)
                stats["active_" + ("th" if level == "TH" else "thcs")] += 1
                if _map_position(row.get("position")) == "GIAO_VIEN":
                    stats["active_teacher_" + ("th" if level == "TH" else "thcs")] += 1

        for (level, school_id), rows in per_school_level.items():
            form_code = "TH_01_GV" if level == "TH" else "THCS_01_GV"
            source_data = _aggregate_staff(level, rows)
            structured = db.scalar(
                select(SchoolStructuredReportInput).where(
                    SchoolStructuredReportInput.school_id == school_id,
                    SchoolStructuredReportInput.school_year_id == int(year.id),
                    SchoolStructuredReportInput.form_code == form_code,
                )
            )
            if structured is None:
                structured = SchoolStructuredReportInput(
                    school_id=school_id,
                    school_year_id=int(year.id),
                    form_code=form_code,
                    data_json=json.dumps(source_data, ensure_ascii=False, separators=(",", ":")),
                    notes=f"Tự động tổng hợp từ danh sách đội ngũ {source_year_code}",
                )
                db.add(structured)
                stats["structured_created"] += 1
            else:
                try:
                    existing = json.loads(structured.data_json or "{}")
                except Exception:
                    existing = {}
                if not isinstance(existing, dict):
                    existing = {}
                merged = dict(source_data)
                merged.update(existing)  # dữ liệu đã nhập thủ công luôn thắng
                structured.data_json = json.dumps(merged, ensure_ascii=False, separators=(",", ":"))
                stats["structured_updated"] += 1

        db.commit()

        stats["schools_total"] = int(db.scalar(select(func.count(School.id))) or 0)
        stats["network_total"] = int(db.scalar(select(func.count(SchoolNetworkYearData.id))) or 0)
        stats["staff_members_total"] = int(db.scalar(select(func.count(StaffMember.id))) or 0)
        stats["staff_year_records_total"] = int(
            db.scalar(
                select(func.count(StaffYearRecord.id)).where(
                    StaffYearRecord.school_year_id == int(year.id)
                )
            ) or 0
        )
        stats["structured_gv_total"] = int(
            db.scalar(
                select(func.count(SchoolStructuredReportInput.id)).where(
                    SchoolStructuredReportInput.school_year_id == int(year.id),
                    SchoolStructuredReportInput.form_code.in_(["TH_01_GV", "THCS_01_GV"]),
                )
            ) or 0
        )
        stats["unmatched_communes"] = sorted(stats["unmatched_communes"])
        return stats
    finally:
        db.close()


def _verify_after() -> None:
    checks = {
        "app/report_input_models.py": ["class SchoolNetworkYearData"],
        "app/routers/report_inputs.py": ["BAI_13B_6_V1_2_NETWORK_DATA_START"],
        "app/pcgd_xmc_report_builders_v1.py": [
            "BAI_13B_6_V1_2_NETWORK_EXPORT_START",
            "teaching_subject",
            "main_specialty",
        ],
        "app/staff_models.py": [
            "ethnic_group",
            "teaching_subject",
            "main_specialty",
            "staff_evaluation",
        ],
        "app/routers/staff_management.py": [
            '"TIEU_HOC": "Tiểu học"',
            '"THCS": "Trung học cơ sở"',
            "staff_evaluation",
        ],
        "app/templates/staff/list.html": ["record.staff_evaluation", "record.staff_member.ethnic_group"],
        "app/templates/staff/form.html": ["teaching_subject", "staff_evaluation"],
    }
    for rel, markers in checks.items():
        text = _read_text(rel)
        for marker in markers:
            if marker not in text:
                raise RuntimeError(f"Kiểm tra sau cài không đạt: {rel} / {marker}")


def _clear_cache() -> None:
    for cache in APP.rglob("__pycache__"):
        if cache.is_dir():
            shutil.rmtree(cache, ignore_errors=True)


